56	// KeyValue is the UDT representation of a Jaeger KeyValue.
57	type KeyValue struct {
58		Key          string  `cql:"key"`
59		ValueType    string  `cql:"value_type"`
60		ValueString  string  `cql:"value_string" json:"value_string,omitempty"`
61		ValueBool    bool    `cql:"value_bool" json:"value_bool,omitempty"`
62		ValueInt64   int64   `cql:"value_long" json:"value_long,omitempty"`     // using more natural column name for Cassandra
63		ValueFloat64 float64 `cql:"value_double" json:"value_double,omitempty"` // using more natural column name for Cassandra
64		ValueBinary  []byte  `cql:"value_binary" json:"value_binary,omitempty"`
65	}
66	
67	func (t *KeyValue) compareValues(that *KeyValue) int {
68		switch t.ValueType {
69		case StringType:
70			return strings.Compare(t.ValueString, that.ValueString)
71		case BoolType:
72			if t.ValueBool != that.ValueBool {
73				if !t.ValueBool {
74					return -1
75				}
76				return 1
77			}
78		case Int64Type:
79			return int(t.ValueInt64 - that.ValueInt64)
80		case Float64Type:
81			if t.ValueFloat64 != that.ValueFloat64 {
82				if t.ValueFloat64 < that.ValueFloat64 {
83					return -1
84				}
85				return 1
86			}
87		case BinaryType:
88			return bytes.Compare(t.ValueBinary, that.ValueBinary)
89		default:
90			return -1 // theoretical case, not stating them equal but placing the base pointer before other
91		}
92		return 0
93	}
94	
95	func (t *KeyValue) Compare(that any) int {
96		if that == nil {
97			if t == nil {
98				return 0
99			}
100			return 1
101		}
102		that1, ok := that.(*KeyValue)
103		if !ok {
104			that2, ok := that.(KeyValue)
105			if !ok {
106				return 1
107			}
108			that1 = &that2
109		}
110		if that1 == nil {
111			if t == nil {
112				return 0
113			}
114			return 1
115		} else if t == nil {
116			return -1
117		}
118		if cmp := strings.Compare(t.Key, that1.Key); cmp != 0 {
119			return cmp
120		}
121		if cmp := strings.Compare(t.ValueType, that1.ValueType); cmp != 0 {
122			return cmp
123		}
124		return t.compareValues(that1)
125	}
126	
127	func (t *KeyValue) Equal(that any) bool {
128		return t.Compare(that) == 0
129	}
130	
131	func (t *KeyValue) AsString() string {
132		switch t.ValueType {
133		case StringType:
134			return t.ValueString
135		case BoolType:
136			if t.ValueBool {
137				return "true"
138			}
139			return "false"
140		case Int64Type:
141			return strconv.FormatInt(t.ValueInt64, 10)
142		case Float64Type:
143			return strconv.FormatFloat(t.ValueFloat64, 'g', 10, 64)
144		case BinaryType:
145			return hex.EncodeToString(t.ValueBinary)
146		default:
147			return "unknown type " + t.ValueType
148		}
149	}
150	
151	func SortKVs(kvs []KeyValue) {
152		slices.SortFunc(kvs, func(a, b KeyValue) int {
153			return a.Compare(b)
154		})
155	}
156	
157	func compareKVs(a, b []KeyValue) int {
158		if lenComp := len(a) - len(b); lenComp != 0 {
159			return lenComp
160		}
161		return slices.CompareFunc(a, b, func(a KeyValue, b KeyValue) int {
162			return a.Compare(b)
163		})
164	}
165	
166	func SortLogs(logs []Log) {
167		for _, log := range logs {
168			SortKVs(log.Fields)
169		}
170		slices.SortFunc(logs, func(a, b Log) int {
171			if timeComp := compareInt64(a.Timestamp, b.Timestamp); timeComp != 0 {
172				return timeComp
173			}
174			return compareKVs(a.Fields, b.Fields)
175		})
176	}
177	
178	func SortSpanRefs(spanRefs []SpanRef) {
179		slices.SortFunc(spanRefs, func(a, b SpanRef) int {
180			if traceIDComp := bytes.Compare(a.TraceID[:], b.TraceID[:]); traceIDComp != 0 {
181				return traceIDComp
182			}
183			if spanIDComp := compareInt64(a.SpanID, b.SpanID); spanIDComp != 0 {
184				return spanIDComp
185			}
186			return strings.Compare(a.RefType, b.RefType)
187		})
188	}
189	
190	func compareInt64(a, b int64) int {
191		if a < b {
192			return -1
193		}
194		if a > b {
195			return 1
196		}
197		return 0
198	}
199	
200	// Log is the UDT representation of a Jaeger Log.
201	type Log struct {
202		Timestamp int64      `cql:"ts"` // microseconds since epoch
203		Fields    []KeyValue `cql:"fields"`
204	}
205	
206	// SpanRef is the UDT representation of a Jaeger Span Reference.
207	type SpanRef struct {
208		RefType string  `cql:"ref_type"`
209		TraceID TraceID `cql:"trace_id"`
210		SpanID  int64   `cql:"span_id"`
211	}
212	
213	// Process is the UDT representation of a Jaeger Process.
214	type Process struct {
215		ServiceName string     `cql:"service_name"`
216		Tags        []KeyValue `cql:"tags"`
217	}
218	
219	// TagInsertion contains the items necessary to insert a tag for a given span
220	type TagInsertion struct {
221		ServiceName string
222		TagKey      string
223		TagValue    string
224	}
225	
226	func (t TagInsertion) String() string {
227		const uniqueTagDelimiter = ":"
228		var buffer bytes.Buffer
229		buffer.WriteString(t.ServiceName)
230		buffer.WriteString(uniqueTagDelimiter)
231		buffer.WriteString(t.TagKey)
232		buffer.WriteString(uniqueTagDelimiter)
233		buffer.WriteString(t.TagValue)
234		return buffer.String()
235	}
236	
237	// Trace is a collection of spans with the same trace ID.
238	type Trace struct {
239		Spans []Span
240	}
241	
242	// TraceIDFromDomain converts domain TraceID into serializable DB representation.
243	func TraceIDFromDomain(traceID model.TraceID) TraceID {
244		dbTraceID := TraceID{}
245		binary.BigEndian.PutUint64(dbTraceID[:8], uint64(traceID.High))
246		binary.BigEndian.PutUint64(dbTraceID[8:], uint64(traceID.Low))
247		return dbTraceID
248	}
