}

func (b *withConfigBuilder) build() (*cassandra.Factory, error) {
	b.f.ConfigureFromOptions(b.opts)
	if err := b.opts.Configuration.Validate(); err != nil {
		return nil, err
	}
	err := b.initializer(b.metricsFactory, b.logger, b.tracer)
	if err != nil {
		return nil, err
	}
	return b.f, nil
