	}
	tracerProvider, tracerCloser, err := jtracer.NewProvider(context.Background(), "savetracetest")
	if err != nil {
		logger.Fatal("Failed to initialize tracer", zap.Error(err))
	}
	defer tracerCloser(context.Background())
